window.OVA_CONTENT={"slug":"seccion-03-biotecnologia-y-decision-responsable","title":"Biotecnología y decisión responsable","minutes":45,"summary":"Diferencia PCR, clonación y edición génica y evalúa sus aplicaciones, límites y responsabilidades.","objective":"Analizar herramientas biotecnológicas según la pregunta, la evidencia y el riesgo asociado.","stages":[{"eyebrow":"Herramientas","title":"1. Una técnica para cada propósito","reading":"La PCR amplifica una región específica de ADN; la clonación genera copias de material genético, células u organismos según el contexto; CRISPR permite editar sitios determinados del material genético.","application":"Nombrar una técnica no demuestra que sea apropiada: primero debe definirse la pregunta productiva o diagnóstica.","activity":{"type":"match","question":"Relaciona técnica y función general.","pairs":[{"label":"PCR","value":"amplificar","option":"Amplificar una región de ADN"},{"label":"Clonación","value":"copias","option":"Obtener copias biológicas"},{"label":"CRISPR","value":"editar","option":"Modificar una secuencia específica"}],"answer":["amplificar","copias","editar"],"success":"La selección depende del propósito."}},{"eyebrow":"PCR","title":"2. Qué ocurre en una amplificación","reading":"En una PCR, ciclos de separación de hebras, unión de iniciadores y extensión permiten multiplicar una región. El resultado debe interpretarse con controles y respecto de una pregunta concreta.","application":"Una señal sin control puede reflejar contaminación, error de muestreo o amplificación no específica.","activity":{"type":"order","question":"Ordena el flujo de una prueba molecular responsable.","items":["Definir la región objetivo","Tomar y registrar la muestra","Amplificar con controles","Leer el resultado","Interpretar dentro del contexto"],"answer":[0,1,2,3,4],"success":"La trazabilidad comienza antes del laboratorio."}},{"eyebrow":"Aplicaciones","title":"3. Posibilidades en agroindustria","reading":"Las herramientas moleculares pueden apoyar identificación varietal, detección de organismos, selección asistida, trazabilidad y estudio de rasgos. Su utilidad depende de calidad de muestra, método y referencia.","application":"No reemplazan automáticamente controles de proceso, inspecciones, evaluación agronómica o análisis de inocuidad.","activity":{"type":"multi","question":"Selecciona aplicaciones plausibles.","options":["Identificación de material vegetal","Apoyo a detección de un patógeno","Garantizar por sí sola toda la calidad del lote","Comparar perfiles genéticos"],"answer":[0,1,3],"success":"La biotecnología aporta evidencia específica, no una garantía total."}},{"eyebrow":"Bioseguridad","title":"4. Capacidad técnica y responsabilidad","reading":"Una tecnología puede ofrecer beneficios y, al mismo tiempo, generar incertidumbres ambientales, sociales o regulatorias. La evaluación responsable considera alcance, posibles efectos, reversibilidad, monitoreo y normas aplicables.","application":"El origen biológico o la precisión de una técnica no eliminan la necesidad de gestión del riesgo.","activity":{"type":"choice","question":"¿Qué criterio debe anteceder la adopción?","options":["Evaluar beneficios, riesgos, controles y regulación","Asumir que toda innovación es segura","Decidir únicamente por la novedad"],"answer":[0],"success":"Innovar exige evidencia y condiciones de uso."}},{"eyebrow":"Caso aplicado","title":"5. Edición para resistencia","reading":"Una empresa estudia material editado para resistencia a una enfermedad. Además del rasgo, debe analizar desempeño, estabilidad, interacción ambiental, acceso tecnológico y requisitos de autorización.","application":"La decisión debe documentar qué problema resuelve y cómo se vigilarán efectos no previstos.","activity":{"type":"choice","question":"¿Cuál evidencia es insuficiente por sí sola?","options":["Que el gen objetivo fue modificado","Ensayos de desempeño","Plan de monitoreo"],"answer":[0],"success":"Confirmar la edición no demuestra todo el comportamiento productivo."}}],"number":"03","references":["Audesirk, T. et al. (2017). Biología: La vida en la tierra con fisiología. Pearson Educación.","Freeman, S. (2009). Biología. Pearson Educación.","Gutiérrez Ramírez, L. A. (2016). Los microorganismos en la agroindustria. Editorial Lasallista.","Mader, S. S. (2024). Biología. McGraw-Hill.","Velázquez Ocampo, M. P. (2020). Biología II. Cengage Learning."]};